        || !(verdict.kind.is_empty() || verdict.kind == "quota-unknown-reset")
    {
        return verdict;
    }
    let Some(hits) = health.map(|h| &h.instant_429s).filter(|h| h.len() >= 2) else {
        return verdict;
    };
    // the newest hit and the newest earlier one within the hour
    let second = hits[0];
    let Some(first) = hits[1..]
        .iter()
