fn machine_consults_filtered(path: &Path, fingerprint: Option<&str>) -> Vec<Value> {
    read_machine_health(path)
        .endpoints
        .into_iter()
        .filter(|e| fingerprint.is_none_or(|fp| e.endpoint == fp))
        .filter_map(|e| {
            let mut v = serde_json::json!({
                "when": e.when,
                "n": 0,
                "finished_at": e.when,
                "reviewer": { "provider_fingerprint": e.endpoint },
                // (wave 9b, F66-3) a synthetic consultation: marked, and carrying the consult id
                // when the record has one
                "machine": true,
            });
            if !e.consult_id.is_empty() {
                v["consult_id"] = Value::String(e.consult_id.clone());
            }
            if e.class.is_empty() {
                // (wave 8 = plugin wave 30) a record of class '' carries only the quota windows of
                // a run: no outcome (a record without a class and without them is skipped)
                let q = e.quota.clone()?;
                v["bridge_outcome"] = Value::String(String::new());
                v["provider_failure"] = Value::Null;
                v["quota"] = q;
                return Some(v);
            }
            if e.class == "ok" {
                v["bridge_outcome"] = Value::String("usable reply".into());
                // (wave 29b, E15) a usable reply with a quota mark: the mark travels as
                // engine_run.quota_mark (its own when, reset and until when valid)
                if let Some(mk) = e.quota_mark.as_ref().filter(|m| m.is_object()) {
                    let valid = |k: &str| -> Value {
                        if dto(&mk[k]).is_some() {
                            mk[k].clone()
                        } else {
                            Value::Null
                        }
                    };
                    let when = if dto(&mk["when"]).is_some() {
                        mk["when"].clone()
                    } else {
                        Value::String(e.when.clone())
                    };
                    v["engine_run"] = serde_json::json!({
                        "quota_mark": {
                            "class": "quota",
                            "kind": mk["kind"].as_str().unwrap_or(""),
                            "code": "",
                            "message": mk["message"].as_str().unwrap_or(""),
                            "when": when,
                            "retry_after": valid("retry_after"),
                            "until": valid("until"),
                        }
                    });
                }
